SET training_id = 'rsm_sales_incentive_plan_cany_fiber', status = 'draft', notes = 'Moved from rsm_sales_incentive_plan (draft #31) on 2026-10-06 for CA/NY Fiber stores. Store-type tags removed; this training teaches its own Power Rank weights in topic 4 (moved there from topic 1, whose original opening is restored). Check it, make a preview call, then submit.',
    content = '{"quiz": {"sections": {"A": {"name": "Compensation eligibility requirements", "topics": [1]}, "B": {"name": "Personal Sales Quota (PSQ) definition", "topics": [2]}, "C": {"name": "Plus One credit rule", "topics": [2]}, "D": {"name": "Power Rank qualifiers", "topics": [5]}, "E": {"name": "\\tPerfect 10 bonus and store incentive eligibility", "topics": [7]}}, "questions": [{"number": 1, "correct": "A", "options": {"A": "Meet their PSQ and reach 100% monthly mandatory compliance training completion for themselves and their store employees", "B": "Reach Power Rank 8.0 and complete their own training", "C": "Meet their PSQ and work 80 hours in-store"}, "section": "A", "question": "What must an RSM do to receive full compensation for personal and store sales?", "explanation": "It''s both — meet your Personal Sales Quota, and hit 100% completion on mandatory compliance training, not just for yourself but for your whole store''s employees too."}, {"number": 2, "correct": "B", "options": {"A": "5 Premium Products", "B": "10 Premium Products", "C": "10 activations of any type"}, "section": "B", "question": "What is the monthly RSM Personal Sales Quota, or PSQ?", "explanation": "Your PSQ is 10 Premium Products a month."}, {"number": 3, "correct": "B", "options": {"A": "Upgrades, accessories, and protection", "B": "PPVGA, new internet sales, and new DirecTV sales", "C": "Prepaid activations, upgrades, and tablets"}, "section": "B", "question": "Which sales count as Premium Products toward the PSQ?", "explanation": "Premium Products are PPVGA, new Internet sales, and new DirecTV sales."}, {"number": 4, "correct": "C", "options": {"A": "Each counts as one Premium Product, with no limit", "B": "Plus One sales do not count toward PSQ", "C": "Each counts as 0.5 of a Premium Product, up to five Premium Products of credit per month"}, "section": "C", "question": "How do Plus One sales count toward PSQ attainment?", "explanation": "Each Plus One counts as half a Premium Product, capped at 5 Premium Products of credit a month."}, {"number": 5, "correct": "A", "options": {"A": "2", "B": "2.5", "C": "5"}, "section": "C", "question": "An RSM sells five Plus One devices. How many whole Premium Products count toward their PSQ?", "explanation": "Two. Five Plus Ones at 0.5 each is 2.5 — odd numbers round down."}, {"number": 6, "correct": "B", "options": {"A": "The category earns no points", "B": "The category''s points are reduced by 50%", "C": "The entire Power Rank is reduced by 50%"}, "section": "D", "question": "What happens to the points in a Power Rank category if the store misses that category''s qualifier?", "explanation": "Just that one category''s points get cut by 50%."}, {"number": 7, "correct": "B", "options": {"A": "50% Next Up and 5% HTP", "B": "70% Next Up and 8% HTP", "C": "80% Next Up and 10% HTP"}, "section": "D", "question": "What are the Next Up and HTP qualifier targets?", "explanation": "70% for Next Up, 8% for HTP."}, {"number": 8, "correct": "C", "options": {"A": "A $250 bonus", "B": "A $500 bonus instead of unit payouts", "C": "A $500 bonus in addition to applicable top-tier payouts"}, "section": "E", "question": "What does a store manager earn for achieving a final Power Rank of 10.0?", "explanation": "A $500 bonus — on top of your top-tier unit payouts, not instead of them."}, {"number": 9, "correct": "B", "options": {"A": "60 hours", "B": "80 hours", "C": "100 hours"}, "section": "E", "question": "How many hours must a store manager work in-store during the applicable calendar month to be eligible for a Monthly Store Incentive payout?", "explanation": "80 hours in-store, minimum."}, {"number": 10, "correct": "B", "options": {"A": "The RSM receives full personal and store sales incentives because they met their PSQ", "B": "The RSM loses applicable personal sales incentives, and their store incentive is reduced by 50%", "C": "The RSM receives full incentives because they worked more than 80 hours in-store"}, "section": "A", "question": "Scenario: An RSM sells 10 eligible Premium Products and works 100 hours in-store during October. The RSM completes all assigned training, but one store employee has not completed a required monthly compliance course. What happens to the RSM''s incentives?", "explanation": "The compliance requirement covers your whole store — one employee''s incomplete training costs the RSM their personal sales incentives, plus a 50% reduction to their store incentive, even with a perfect PSQ and hours."}]}, "format": 1, "training": {"lines": {"closing": "Great work — you''ve completed this quarter''s RSM compensation training! Keep an eye on your Power Ranks and the Power Rank Definitions chart on My Page, and partner with your district manager anytime you want to build a plan to move your store up a tier. Thanks for taking the time today!", "quiz_intro": "That covers the full RSM compensation plan, {trainer_name}. Now let''s put it to the test — I''ll ask you 10 questions covering everything we just went through. You''ll need all 10 correct to complete this training, and if you miss any, we''ll go back over just those areas together.", "first_message": "Hey! I''m {trainer_name}, your trainer for the RSM Sales Incentive Plan and Power Ranks for October 2026. We''ll walk through what''s new — eligibility requirements, your personal and store sales incentives, and how your store''s Power Rank is calculated — and it should take about 10 to 15 minutes. Here''s how it''ll go: first we''ll cover everything together, then you''ll take a mandatory 10-question quiz — you''ll need to get all 10 right to complete the training. Ready to get started?", "perfect_score": "That''s a perfect score! You''ve shown you know exactly what it takes to earn every dollar you''re owed this quarter.", "already_passed": "Welcome back! You''ve already completed this quarter''s RSM compensation training — nice work. Would you like a quick refresher on anything, like how your store''s Power Rank is calculated, or are you all set?", "location_unknown": "Quick context — there are five location types: Alaska stores; any store or mall in California or New York with Fiber; any store or mall in California or New York that''s AIA-only; Fiber locations outside Alaska, California, and New York; and AIA-only locations outside those states. Do you know which one applies to your store?", "feedback_question": "Before we wrap up — on a scale of 1 to 10, how would you rate this training? And in a sentence or two, what worked for you and what didn''t?", "welcome_back_quiz": "Welcome back! You''ve finished the walkthrough, so let''s jump straight into the quiz.", "passed_after_retry": "You''ve got them all now — nice work sticking with it. You''ve shown you know exactly what it takes to earn every dollar you''re owed this quarter.", "welcome_back_retry": "Welcome back! You already have some sections locked in, so we''ll go back over just the ones you missed.", "welcome_back_walkthrough": "Welcome back! Let''s pick up right where we left off."}, "title": "RSM Sales Incentive Plan- CA/NY Fiber", "company": "Prime Communications", "opening": [{"ask": "Do you have your October 2026 RSM Sales Incentive Plan and your Power Rank schedule pulled up or printed and ready to go right now?", "otherwise": "No problem — you''ll find both the Sales Incentive Plan and your Power Rank schedule under My Pay, on the Human Resources page. Go ahead and pull those up or print them, then just start a new session with me whenever you''re ready to continue."}, {"ask": "Has your district manager or market director had a chance to review your sales incentive plan and Power Ranks with you yet?", "otherwise": "For best results and understanding, have your supervisor review these important topics with you in person before completing this course. For now, let''s continue."}], "trainer_name": "Anne", "uses_location": false, "stt_vocabulary": "nudgelab-rsm-sales-incentive-plan-v26", "completion_type": "quiz"}, "vocabulary": ["P.P.V.G.A.", "H.T.P.", "A.I.A.", "P.S.Q.", "C.R.U.", "First-Net", "Protect-Advantage", "Next-Up", "Plus-One", "Direc-T.V."], "knowledge_base": {"topics": [{"lines": [{"kind": "say_exactly", "text": "In addition to hourly wages, you have the opportunity to earn additional compensation through our Sales Incentive plans — for both your personal sales and your store''s sales. To get full credit for both, there are two requirements: meet your Personal Sales Quota, and hit 100% completion on your monthly mandatory compliance training.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "What are the two requirements to get full credit on your sales incentives?", "prefix": "Ask: "}, {"kind": "expected", "text": "Meet your PSQ, and 100% completion on monthly mandatory compliance training.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "The two requirements are meeting your Personal Sales Quota, and hitting 100% completion on your monthly mandatory compliance training.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "That compliance piece covers not just your own training, but your whole store''s employees too.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Just to make sure that''s clear — whose compliance training counts toward that 100% requirement, yours or your store''s?", "prefix": "Ask: "}, {"kind": "expected", "text": "Both.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly — miss it for even one employee, and it affects your incentives, not just theirs.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "It counts both — yours and every employee in your store.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "One flag for this quarter — Flagship store managers are now required to meet a PSQ as well, which wasn''t the case before.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "True or false — Flagship store managers already had a PSQ requirement before this quarter.", "prefix": "Ask: "}, {"kind": "expected", "text": "False — this is new this quarter.", "prefix": "Expected: "}, {"kind": "if_right", "text": "That''s right.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "It''s false — Flagship store managers did not have a PSQ requirement before. It''s new this quarter.", "prefix": "If they miss it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Compensation Eligibility Requirements", "number": 1}, {"lines": [{"kind": "say_exactly", "text": "Your PSQ is 10 Premium Products a month. Premium Products are PPVGA, new Internet sales, and new DirecTV sales.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "What counts as a Premium Product toward your PSQ?", "prefix": "Ask: "}, {"kind": "expected", "text": "PPVGA, new Internet sales, and new DirecTV sales.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "Premium Products are PPVGA, new Internet sales, and new DirecTV sales.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "Plus One sales — postpaid tablets and wearables — count as half a Premium Product each, capped at 5 Premium Products of credit a month, and odd numbers round down to the nearest whole number.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "If you sell five Plus One devices in a month, how many whole Premium Products does that count toward your PSQ?", "prefix": "Ask: "}, {"kind": "expected", "text": "2", "prefix": "Expected: "}, {"kind": "if_right", "text": "That''s right — five at half each is 2.5, rounded down to 2.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "It''s 2. Five Plus Ones at half each is 2.5, and odd numbers round down.", "prefix": "If they miss it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Personal Sales Quota (PSQ) and Premium Products", "number": 2}, {"lines": [{"kind": "say_exactly", "text": "When you meet your PSQ and training requirements, you earn sales incentives on your own personal sales — on top of whatever your store earns through Store Sales Incentives, not instead of it. For personal sales, you''ll receive $5 for every activation — that''s new PPVGA, Internet, Upgrades, Plus Ones, and DirecTV — or $10 per activation if you''re at a Regular store.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Quick check — if you''re at a Regular store, how much do you personally earn for each qualifying activation?", "prefix": "Ask: "}, {"kind": "expected", "text": "$10", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "It''s $10 per activation at a Regular store — $5 at Flagship.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "You''ll also earn 5% of all accessories you personally sell — 7% at Regular stores — and $3 for every Protection product, including Protect Advantage or HTP. One note if you''re at a Flagship location — personal sales commissions are capped at $250.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "And what''s the personal commission cap at a Flagship store?", "prefix": "Ask: "}, {"kind": "expected", "text": "$250", "prefix": "Expected: "}, {"kind": "if_right", "text": "That''s right.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "The cap is $250 at a Flagship store.", "prefix": "If they miss it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Personal Sales Incentives", "number": 3}, {"lines": [{"kind": "say_exactly", "text": "Your store''s Power Rank is a weighted scoring system out of 10, built from eight metrics tied to your store''s sales performance against its goals.  For your California and New York or Fiber Mall location, the top of your Power Rank is 30% PPVGA, 20% Fiber, 10% AIA, and 10% Accessories. The rest is 10% Protection with the HTP qualifier, 10% Opps, 5% Next Up, and 5% CRU and FirstNet.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Which metric carries the most weight in your store''s Power Rank?", "prefix": "Ask: "}, {"kind": "expected", "text": "PPVGA", "prefix": "Expected: "}, {"kind": "accept", "text": "Postpaid voice, voice, VGA, voice lines, new lines, new wireless service, postpaid phone voice gross adds — anything naming the same metric.", "prefix": "Accept: "}, {"kind": "if_right", "text": "Correct — PPVGA carries the most weight in your Power Rank.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "It''s PPVGA — it carries the most weight at every location.", "prefix": "If they miss it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": "Your Store''s Power Rank Structure", "number": 4}, {"lines": [{"kind": "say_exactly", "text": "Here''s how to read your store''s Power Rank: a 10.0 is Elite — you''ve mastered the most important metrics and exceeded volume expectations. 9.0 to 9.9 is Top Performer — the top 15 to 20% of stores hit this most months. 8.0 to 8.9 is Above Average, and should be the minimum floor every store aims for. 7.0 to 7.9 is Average, 6.0 to 6.9 is Below Average, and below 6.0 is poor performance — the lowest payouts, and it can lead to disciplinary action.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "What range should be the minimum floor every store aims for?", "prefix": "Ask: "}, {"kind": "expected", "text": "8.0 to 8.9 (Above Average).", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "The minimum floor is 8.0 to 8.9, which is Above Average.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "Some categories here have qualifiers — miss one, and that category''s points get cut by 50%. Right now the qualifier is Protection: you need at least an 8% HTP attach rate. Total Opportunities also has a qualifier — a 70% Next Up attach rate on eligible opportunities.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "What''s the HTP qualifier target for Protection?", "prefix": "Ask: "}, {"kind": "expected", "text": "8% attach rate.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "The HTP qualifier is an 8% attach rate.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "One more thing to know: Power Ranks round down to one decimal, and your store''s volume targets are calculated monthly and published for all RSMs by the 3rd of the month.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "True or false — a Power Rank of 9.05 would show as 9.1.", "prefix": "Ask: "}, {"kind": "expected", "text": "False — it rounds down to 9.0.", "prefix": "Expected: "}, {"kind": "if_right", "text": "That''s right.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "It''s false — Power Ranks round down, so 9.05 shows as 9.0.", "prefix": "If they miss it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Power Rank Benchmarks and Qualifiers", "number": 5}, {"lines": [{"kind": "say_exactly", "text": "Store managers also earn monthly incentives on everything their store sells, and the payout scales directly with your store''s Power Rank — the higher your Power Rank, the more you earn per PPVGA, per Internet sale, per Upgrade, and on accessories. The exact payout at every tier is laid out in your Sales Incentive Plan in front of you.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Assuming you''ve met your PSQ and all store compliance training is complete, how much will you earn per PPVGA sold if your store ends the month with a Power Rank of 8.0?", "prefix": "Ask: "}, {"kind": "expected", "text": "$15", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly right.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "Take a look at your plan under the 8.0 to 8.9 tier — you''ll see $15 per PPVGA. It''s worth knowing exactly where to find that for any tier.", "prefix": "If they miss it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Monthly Store Incentive Payout Table", "number": 6}, {"lines": [{"kind": "say_exactly", "text": "If your store hits a perfect Power Rank of 10.0, you earn an extra $500 cash bonus — on top of your top-tier unit payouts, not instead of them.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Does that $500 bonus replace your top-tier payouts, or come on top of them?", "prefix": "Ask: "}, {"kind": "expected", "text": "On top of them — in addition, not instead.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "It comes on top of your top-tier payouts, not instead of them.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "To be eligible for a Monthly Store Incentive payout at all, you need to work a minimum of 80 hours in-store in that calendar month.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "How many hours must you work in-store that month to be eligible for a Monthly Store Incentive payout at all?", "prefix": "Ask: "}, {"kind": "expected", "text": "80 hours.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "It''s 80 hours in-store, minimum.", "prefix": "If they miss it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Perfect 10 Bonus and Store Incentive Eligibility", "number": 7}, {"lines": [{"kind": "say_exactly", "text": "A few things make the biggest difference for your store''s payout. First, PPVGA — it''s the highest-weighted metric everywhere, and the highest-paying. Second, Internet — remember, a customer can''t be eligible for both AT&T Fiber and AIA, so when your team sees an eligible opportunity, a green check, your job is to make sure they''re pitched the top offer every time. If a customer can''t sign up today, make sure it gets loaded into CCLM as a lead for a follow-up call.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "How can you check that your employees are actually executing on this and maximizing every opportunity?", "prefix": "Ask: "}, {"kind": "expected", "text": "Sales observations.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly — observing those interactions is how you coach in the moment.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "Sales observations — watching those live customer interactions is how you catch and coach this in the moment.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "Third, Accessories — take your store''s accessory target and multiply it by 5% to see what that category alone is worth; it''s your second-highest-paying category after PPVGA.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Say your store is missing its accessory target. What could you do with your team throughout the day to improve that?", "prefix": "Ask: "}, {"kind": "expected", "text": "Any reasonable idea, for example: role-playing accessory objections, bringing accessories out during every customer interaction, demonstrating accessories, or practicing \\"hold it until you sell it.\\"", "prefix": "Expected: "}, {"kind": "if_right", "text": "Good idea — that''s the kind of thing that moves the accessory number.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "A few ideas: role-play accessory objections with your team, bring accessories out in every customer interaction, demonstrate them, or practice holding it until you sell it.", "prefix": "If they miss it: "}, {"kind": "text", "text": "", "prefix": ""}], "title": " Maximizing Your Store''s Payouts", "number": 8}, {"lines": [{"kind": "say_exactly", "text": "A few more details. All unit payouts — personal and store — are subject to a 180-day chargeback period for cancellations. \\"Other\\" opportunities include postpaid tablets and watches, new broadband under 300 Mbps, copper-to-fiber upgrades, DirecTV, prepaid voice activations, Fleet Complete, and MiFi devices.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Quick check — what''s the chargeback period on unit payouts?", "prefix": "Ask: "}, {"kind": "expected", "text": "180 days.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "The chargeback period is 180 days.", "prefix": "If they miss it: "}, {"kind": "say_exactly", "text": "A couple of caps to know: PPVGA on Value Plus plans is capped at $5 for the Monthly Store Bonus, voice upgrades on Value Plus rate plans aren''t eligible for sales incentives at all, and only prepaid activations on plans with an MRC of $35 or more qualify.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Quick check: a rep activates a prepaid line on a $30 MRC plan. Does that count toward sales incentives?", "prefix": "Ask: "}, {"kind": "expected", "text": "No. Only prepaid activations on plans with an MRC of $35 or more qualify.", "prefix": "Expected: "}, {"kind": "if_missed", "text": "Actually, it doesn''t. Only prepaid activations on plans with an MRC of $35 or more qualify.", "prefix": "If they miss it: "}, {"kind": "if_right", "text": "You got it! Only prepaid activations on plans with an MRC of $35 or more qualify.", "prefix": "If they get it: "}, {"kind": "say_exactly", "text": "For your day-to-day tools: your Power Ranks, Power Rank Definitions, the What-if Estimator, and the Sales Incentive Estimator all live on My Page. Your RSM Pay Plan document is under My Pay, on the Human Resources page. And keep an eye on the Prime Drop App, Prime News emails, or the Portal''s Contests and Incentives page for extra incremental incentives.", "prefix": "Say exactly: "}, {"kind": "ask", "text": "Which tool in the Portal can help you coach your team to maximize their Power Rank?", "prefix": "Ask: "}, {"kind": "expected", "text": "The Sales Incentive Estimator.", "prefix": "Expected: "}, {"kind": "if_right", "text": "Exactly — that''s built for exactly this.", "prefix": "If they get it: "}, {"kind": "if_missed", "text": "The Sales Incentive Estimator — pull it up with your team to show them exactly what different scenarios would earn.", "prefix": "If they miss it: "}], "title": " Other Notes and Where to Find Everything", "number": 9}], "preamble": [], "ends_with_newline": true}}',
    revision = revision + 1, updated_at = UTC_TIMESTAMP(6)
WHERE version_id = 31 AND training_id = 'rsm_sales_incentive_plan' AND status = 'in_review' AND revision = 2;
